export const DECISION_QUESTIONS = [{"question":"יש כמה פעילויות, מעמד פטור במע״מ או הקלה מאושרת?","answer":"לפי 2(ב), כשחלות כמה תוספות מנהלים לפי הפעילות העיקרית בתיאומים סבירים בהתחשב באחרות.2א קובע מינימום למי שסעיף 31(3) למע״מ חל עליו; הקלה אישית נבחנת לפי נוסחה ותחולתה. אין לבחור רק לפי שם המקצוע."},{"question":"העסק מייצר, מעבד, מרכיב או אורז מוצרים? (גם מחומר גלם של הלקוח, גם לפי הזמנה)","answer":"כן ← תוספת א' (יצרנים). מיון ואריזה שנלווים למסחר או לשירות אינם ייצור."},{"question":"העסק מוכר סחורה מתוצרת אחרים - למי?","answer":"בעיקר לעסקים (הסחורה מלאי אצלם) ← תוספת ב' (סיטונאים). לצרכן הסופי ← תוספת ג' (קמעונאים)."},{"question":"העסק מבצע עבודות בניה - בניה חדשה, חפירה, הריסה, ביוב, סלילה?","answer":"כן ← תוספת ד' (קבלנים). שיפוצים ותיקונים בבניינים קיימים ← תוספת יא' עם יומן עבודה."},{"question":"המקצוע ברשימה הסגורה של מקצועות חופשיים או רפואה?","answer":"עו\"ד, רו\"ח, יועץ מס, אדריכל, מהנדס, שמאי וכו' ← ה'. רופא, פסיכולוג, פיזיותרפיסט, וטרינר ← ו'. מקצוע דומה שאינו ברשימה (מתכנת, גרפיקאי) ← יא'."},{"question":"ענף עם תוספת ייעודית?","answer":"לימוד נהיגה ← ז'; בית ספר/גן/חוגים 5+ ← ח'; מקרקעין ← ט'; רכב ← י'; חקלאות ← יב'; דלק ← יד'; ביטוח ← טו'; יהלומים ← טז'."},{"question":"שום דבר לא התאים?","answer":"כן ← תוספת יא' (נותני שירותים ואחרים) - סעיף הסל שחל על כל עסק או משלח יד שלא נכנס לתוספת אחרת."}];